{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.InputSchema",
  "description": "Schema for validating Function input.\n\nDefines the expected structure and constraints for input data.\nUsed by remote Functions to document and validate their inputs.",
  "oneOf": [
    {
      "description": "An object with named properties.",
      "type": "object",
      "properties": {
        "Object": {
          "$ref": "functions.expression.ObjectInputSchema"
        }
      },
      "required": [
        "Object"
      ],
      "additionalProperties": false
    },
    {
      "description": "An array of items.",
      "type": "object",
      "properties": {
        "Array": {
          "$ref": "functions.expression.ArrayInputSchema"
        }
      },
      "required": [
        "Array"
      ],
      "additionalProperties": false
    },
    {
      "description": "A string value.",
      "type": "object",
      "properties": {
        "String": {
          "$ref": "functions.expression.StringInputSchema"
        }
      },
      "required": [
        "String"
      ],
      "additionalProperties": false
    },
    {
      "description": "An integer value.",
      "type": "object",
      "properties": {
        "Integer": {
          "$ref": "functions.expression.IntegerInputSchema"
        }
      },
      "required": [
        "Integer"
      ],
      "additionalProperties": false
    },
    {
      "description": "A floating-point number.",
      "type": "object",
      "properties": {
        "Number": {
          "$ref": "functions.expression.NumberInputSchema"
        }
      },
      "required": [
        "Number"
      ],
      "additionalProperties": false
    },
    {
      "description": "A boolean value.",
      "type": "object",
      "properties": {
        "Boolean": {
          "$ref": "functions.expression.BooleanInputSchema"
        }
      },
      "required": [
        "Boolean"
      ],
      "additionalProperties": false
    },
    {
      "description": "An image (URL or base64).",
      "type": "object",
      "properties": {
        "Image": {
          "$ref": "functions.expression.ImageInputSchema"
        }
      },
      "required": [
        "Image"
      ],
      "additionalProperties": false
    },
    {
      "description": "Audio content.",
      "type": "object",
      "properties": {
        "Audio": {
          "$ref": "functions.expression.AudioInputSchema"
        }
      },
      "required": [
        "Audio"
      ],
      "additionalProperties": false
    },
    {
      "description": "Video content.",
      "type": "object",
      "properties": {
        "Video": {
          "$ref": "functions.expression.VideoInputSchema"
        }
      },
      "required": [
        "Video"
      ],
      "additionalProperties": false
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "File": {
          "$ref": "functions.expression.FileInputSchema"
        }
      },
      "required": [
        "File"
      ],
      "additionalProperties": false
    },
    {
      "description": "A union of schemas - input must match at least one.",
      "type": "object",
      "properties": {
        "AnyOf": {
          "$ref": "functions.expression.AnyOfInputSchema"
        }
      },
      "required": [
        "AnyOf"
      ],
      "additionalProperties": false
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "type": [
        "string",
        "null"
      ]
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "oneOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "const": "auto"
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "const": "low"
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "const": "high"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  },
  "required": [
    "anyOf"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected audio.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Input",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#"
      }
    },
    {
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "#"
      }
    },
    {
      "description": "A string value.",
      "type": "string"
    },
    {
      "description": "An integer value.",
      "type": "integer",
      "format": "int64"
    },
    {
      "description": "A floating-point number.",
      "type": "number",
      "format": "double"
    },
    {
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the integer.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    }
  }
}
